{"cards": [{"node_code": "N_a3cd5e4ac1cce538", "definition": "研究铁路运输中成本构成、核算方法、运价制定机制、票价体系及其经济规律的理论分支，涵盖定价模型与收益分析。", "boundary": "本节点聚焦于“价格与成本”的理论机制。边界在于区分“定价/成本理论”与“具体财务核算”或“工程技术”：涉及抽象的定价模型、边际成本分析、运价弹性及票价结构归入本节点；涉及具体企业的财务报表、会计分录或线路建设造价归入相应管理或工程节点。若涉及特定国家的具体运价表，侧重理论分析归本节点，侧重事实罗列归国别节点。", "includes": ["铁路运输成本核算方法与成本结构分析理论", "运价制定原则、定价模型及运价弹性分析", "旅客票价体系、货运费率结构及收益管理理论"], "excludes": ["铁路线路、机车等基础设施的建设造价与工程技术成本", "具体企业的年度财务报表、审计数据及会计实务操作"], "sibling_distinctions": [{"other_code": "N_07aba58e8d817f26", "rule": "区分依据为“价格机制”与“组织管理”：侧重运价、票价、成本的经济规律与定价策略归入本节点；侧重企业组织架构、人力资源、行政流程及内部管理制度归入铁路企业组织和管理。"}, {"other_code": "N_cb3df5a2ba3980fa", "rule": "区分依据为“服务定价”与“资产经营”：侧重运输服务本身的成本与价格归入本节点；侧重铁路基础设施资产（如土地、线路）的估值、租赁、证券化及资本运作归入轨道交通资产管理与经营。"}], "cross_boundary_rule": "若内容涉及“基于资产成本的运价制定”，若侧重定价公式与成本分摊理论，主挂载本节点；若侧重资产折旧模型与资本回报要求，可关联轨道交通资产管理与经营，但定价结论归本节点。"}, {"node_code": "N_07aba58e8d817f26", "definition": "研究铁路企业（含国有、私营及混合所有制）的组织架构、治理结构、内部管理制度、人力资源配置及运营效率提升的理论分支。", "boundary": "本节点聚焦于“企业内部”的组织与管理理论。边界在于区分“企业内部管理”与“宏观体制”或“具体业务操作”：涉及企业层级、部门设置、绩效考核、企业文化及一般管理原则归入本节点；涉及国家层面的铁路行政体制改革、政企分开政策归入铁路计划与管理体制；涉及具体的列车调度、货运作业流程归入运输业务或管理工程。", "includes": ["铁路企业治理结构、董事会与监事会职能及股东权益理论", "企业内部组织架构设计、部门职能划分及行政管理制度", "铁路人力资源开发、薪酬激励体系及员工管理理论"], "excludes": ["国家铁路行政管理部门的宏观政策制定与行业监管法规", "具体的列车运行图编制、车站作业计划等操作性技术内容"], "sibling_distinctions": [{"other_code": "N_51ba8ce85d911db5", "rule": "区分依据为“微观企业”与“宏观体制”：侧重单个铁路企业的内部组织、管理与效率归入本节点；侧重国家铁路行政体制、政企关系、行业规划及宏观管理政策归入铁路计划与管理体制。"}, {"other_code": "N_4c58781afac5f857", "rule": "区分依据为“通用管理”与“特定类型”：侧重适用于各类铁路企业的通用组织与管理原理归入本节点；侧重特定类型铁路（如地方铁路、专用线、城际铁路）的特殊经营模式与管理策略归入各种铁路的经营与管理。"}], "cross_boundary_rule": "若内容涉及“铁路公司制改革”，若侧重公司内部治理结构优化与管理流程再造，主挂载本节点；若侧重政府与企业的权责划分及宏观政策背景，主挂载铁路计划与管理体制。"}, {"node_code": "N_4c58781afac5f857", "definition": "研究不同类型铁路（如地方铁路、专用铁路、城际铁路、高速铁路等）在经营模式、市场定位、盈利策略及特殊管理需求方面的理论分支。", "boundary": "本节点聚焦于“不同铁路类型”的差异化经营与管理。边界在于区分“类型特异性”与“通用理论”：涉及特定类型铁路（如非国铁、短途城际、工矿专用线）的市场竞争策略、特殊成本结构及针对性管理措施归入本节点；涉及所有铁路企业通用的组织管理原理归入铁路企业组织和管理；涉及特定国家的具体线路案例归入国别节点。", "includes": ["地方铁路、专用铁路及城际铁路的经营模式与盈利分析", "高速铁路、重载铁路等特殊类型铁路的市场定位与竞争策略", "不同产权结构（如PPP、BOT）下铁路项目的管理理论与风险分担"], "excludes": ["适用于所有铁路企业的通用行政管理、人力资源及财务基础理论", "特定国家具体线路的建设历史、运营数据及政策文件"], "sibling_distinctions": [{"other_code": "N_07aba58e8d817f26", "rule": "区分依据为“通用性”与“类型特异性”：侧重不区分铁路类型的通用组织与管理原则归入铁路企业组织和管理；侧重因铁路类型（如地方、专用、城际）不同而产生的特殊经营策略与管理难点归入本节点。"}, {"other_code": "N_a3cd5e4ac1cce538", "rule": "区分依据为“经营策略”与“价格理论”：侧重不同铁路类型的市场定位、竞争分析及整体经营方案归入本节点；侧重各类铁路通用的成本核算方法与运价定价模型归入铁路运输成本、运价与票价理论。"}], "cross_boundary_rule": "若内容涉及“城际铁路票价竞争”，若侧重票价制定的经济学原理，主挂载铁路运输成本、运价与票价理论；若侧重城际铁路相对于高铁或公路的市场定位与整体经营策略，主挂载本节点。"}]}
